Please make this use scanner  public static ArrayList<WeeklyShow> readFile(String fileName) throws IOException {
        ArrayList<WeeklyShow> listWeeklyShows = new ArrayList<WeeklyShow>();
        BufferedReader br = new BufferedReader(new FileReader(fileName));
        String line = br.readLine();
        while ((line = br.readLine()) != null) {
            String[] fields = line.split(",");
            String date = fields[0];
            String showName = fields[1];
            String theater = fields[2];
            String showType = fields[3];
            int attendance = Integer.parseInt(fields[4]);
            int capacity = Integer.parseInt(fields[5]);
            int grossSales = Integer.parseInt(fields[6]);
            int grossPotential = Integer.parseInt(fields[7]);
            int numPerformances = Integer.parseInt(fields[8]);
            WeeklyShow weeklyShow = new WeeklyShow(date, showName, theater, showType, attendance, capacity, grossSales, grossPotential, numPerformances);
            listWeeklyShows.add(weeklyShow);
        }
        br.close();
        return listWeeklyShows;
    }

